Doing so might be a fair bit smaller, and avoids relying on Map.

```js
// checks if a script is *not* already in the DOM
function shouldLoadScript(url) {
  return document.querySelector(`script[src^="${url}"]`) == null;
}

const deps = this.getDependencies(route);
const urlsToLoad = deps
  .map(url => '/_next/' + url)
  .filter(shouldLoadScript);
// etc
```

